templates.faust_skeleton:
import("stdfaust.lib");

room_size = hslider("room_size", {{room_size}}, 0.1, 1.0, 0.01);
damping   = hslider("damping",   {{damping}},   0.0, 1.0, 0.01);
wet_mix   = hslider("wet_mix",   {{wet_mix}},   0.0, 1.0, 0.01);

process = _ <: (ef.reverb_freeverb(room_size, damping, wet_mix)), _ :> _;

import("stdfaust.lib");

delay_ms  = hslider("delay_ms",  {{delay_ms}},  1.0, 2000.0, 1.0);
feedback  = hslider("feedback",  {{feedback}},  0.0,    0.9, 0.01);
wet_mix   = hslider("wet_mix",   {{wet_mix}},   0.0,    1.0, 0.01);

delay_samp = int(delay_ms * ma.SR / 1000.0);
echo       = +~ (de.delay(65536, delay_samp) * feedback);

process = _ <: (echo * wet_mix), (_ * (1.0 - wet_mix)) :> _;

import("stdfaust.lib");

cutoff = hslider("cutoff", {{cutoff}}, 20.0, 20000.0, 1.0);
q      = hslider("resonance", {{q}},   0.5,    10.0, 0.01);

process = _ : fi.resonlp(cutoff, q, 1.0);

import("stdfaust.lib");

cutoff = hslider("cutoff", {{cutoff}}, 20.0, 20000.0, 1.0);
q      = hslider("resonance", {{q}},   0.5,    10.0, 0.01);

process = _ : fi.resonhp(cutoff, q, 1.0);

import("stdfaust.lib");

drive       = hslider("drive",       {{drive}},       0.0, 1.0, 0.01);
output_gain = hslider("output_gain", {{output_gain}}, 0.0, 1.0, 0.01);

process = _ : *(4.0 * drive + 0.1) : ef.cubicnl(0.0) : *(output_gain);

import("stdfaust.lib");

rate  = hslider("rate",  {{rate}},  0.1, 20.0, 0.01);
depth = hslider("depth", {{depth}}, 0.0,  1.0, 0.01);

lfo     = os.osc(rate) * 0.5 + 0.5;
env     = 1.0 - depth * (1.0 - lfo);

process = _ * env;

import("stdfaust.lib");

rate  = hslider("rate",  {{rate}},  0.1,  5.0, 0.01);
depth = hslider("depth", {{depth}}, 0.0,  1.0, 0.01);
mix   = hslider("mix",   {{mix}},   0.0,  1.0, 0.01);

chorus = ef.chorus(rate, depth, 0.0);

process = _ <: (chorus * mix), (_ * (1.0 - mix)) :> _;

import("stdfaust.lib");

bits      = hslider("bit_depth",    {{bits}},      4.0, 16.0, 1.0);
downsample = hslider("downsample",  {{downsample}}, 1.0, 32.0, 1.0);

quant  = ba.bitcrusher(bits, downsample);

process = _ : quant;

import("stdfaust.lib");

threshold = hslider("threshold", {{threshold}}, -80.0, 0.0, 0.1);
attack    = hslider("attack",    {{attack}},      1.0, 200.0, 1.0);
release   = hslider("release",   {{release}},    10.0, 500.0, 1.0);

gate = ef.gate_mono(threshold, attack, release);

process = _ : gate;

import("stdfaust.lib");

threshold = hslider("threshold", {{threshold}}, -60.0,  0.0, 0.1);
ratio     = hslider("ratio",     {{ratio}},       1.0, 20.0, 0.1);
attack    = hslider("attack",    {{attack}},      1.0, 100.0, 1.0);
release   = hslider("release",   {{release}},    10.0, 500.0, 1.0);
makeup    = hslider("makeup_gain",{{makeup}},     0.0,  24.0, 0.1);

comp = co.compressor_mono(ratio, threshold, attack, release);

process = _ : comp : *(ba.db2linear(makeup));
